            JavaScript

    function minOps(arr, k) {

    let ans = Number.MAX_SAFE_INTEGER;

    for (const target of arr) {

        let operations = 0;
        let valid = true;

        for (const x of arr) {

            if (x > target || (target - x) % k !== 0) {
                valid = false;
                break;
            }

            operations += Math.floor((target - x) / k);
        }

        if (valid) {
            ans = Math.min(ans, operations);
        }
    }

    return ans === Number.MAX_SAFE_INTEGER ? -1 : ans;
}

